solution.solution.cpp:
#include <algorithm>

struct Placed { int x, y, w, h; };

class Layout
{
public:
    Layout(int left, int top, int width, int spacingX, int spacingY)
        : m_left{ left }, m_top{ top }, m_width{ width }, m_sx{ spacingX }, m_sy{ spacingY },
          m_origin{ left }, m_lineY{ top } {}

    Placed item(int w, int h)
    {
        int x{ 0 };
        if (m_continue && m_hasLine)
        {
            x = m_nextX;                                   // continue the current line
        }
        else
        {
            if (m_hasLine) m_lineY += m_lineHeight + m_sy;    // start a new line below the last one
            m_lineHeight = 0;
            x = m_left;
        }
        const int right{ m_origin + m_width };
        if (w < 0) w = std::max(0, right - x);
        m_continue = false;
        m_hasLine = true;
        m_lineHeight = std::max(m_lineHeight, h);
        m_nextX = x + w + m_sx;
        return { x, m_lineY, w, h };
    }

    void sameLine() { m_continue = true; }
    void sameLineAt(int x) { m_continue = true; m_nextX = m_left + x; }
    void indent(int d) { m_left += d; }

private:
    int m_left, m_top, m_width, m_sx, m_sy;
    int m_origin;
    int m_lineY;
    int m_lineHeight{ 0 };
    int m_nextX{ 0 };
    bool m_continue{ false };
    bool m_hasLine{ false };
};

unitTests:
static bool at(const Placed& p, int x, int y) { return p.x == x && p.y == y; }
TEST("the example")
{
    Layout l{ 10, 20, 300, 8, 4 };
    CHECK(at(l.item(100, 20), 10, 20));
    CHECK(at(l.item(50, 30), 10, 44));
    l.sameLine();
    CHECK(at(l.item(60, 10), 68, 44));
    const Placed fill{ l.item(-1, 16) };
    CHECK(at(fill, 10, 78));
    CHECK_EQ(fill.w, 300);
}
TEST("same line uses the tallest item for the line") { Layout l{ 0, 0, 200, 5, 2 }; l.item(10, 10); l.sameLine(); l.item(10, 40); CHECK(at(l.item(10, 10), 0, 42)); }
TEST("same line at a column") { Layout l{ 10, 0, 200, 5, 2 }; l.item(30, 10); l.sameLineAt(80); CHECK(at(l.item(20, 10), 90, 0)); }
TEST("fill after an item on the same line") { Layout l{ 0, 0, 100, 4, 2 }; l.item(30, 10); l.sameLine(); const Placed p{ l.item(-1, 10) }; CHECK_EQ(p.x, 34); CHECK_EQ(p.w, 66); }
TEST("indent and unindent") { Layout l{ 0, 0, 100, 4, 2 }; l.item(10, 10); l.indent(20); CHECK(at(l.item(10, 10), 20, 12)); l.indent(-20); CHECK(at(l.item(10, 10), 0, 24)); }
TEST("sameLine before the first item starts normally") { Layout l{ 5, 5, 100, 4, 2 }; l.sameLine(); CHECK(at(l.item(10, 10), 5, 5)); }

